 const [direction,setDirection]=useState('Long'),[amount,setAmount]=useState('500'),[notice,setNotice]=useState(''),[tab,setTab]=useState('Open positions'),[reviewOrder,setReviewOrder]=useState(false),[closeCandidate,setCloseCandidate]=useState(null);
