 const aiItems=aiEvents.map(e=>({id:"ai"+e.id,title:e.title,detail:e.detail,time:new Date(e.time).toLocaleString([], {dateStyle:"medium",timeStyle:"short"}),sortTime:Date.parse(e.time)||0,icon:e.type==="trade-opened"||e.type==="trade-closed"?Bot:History,acDelta:e.acDelta||0,tcDelta:e.tcDelta||0}));
 const closedItems=history.filter(p=>!p.aiManaged).map(p=>({id:"h"+p.id,title:"Practice position closed",detail:p.direction+" · "+p.market+" · "+(Number(p.realizedPnl)>0?"+":"")+money(Number(p.realizedPnl||0))+" TC simulated P&L · "+money(p.tcReturned??p.amount)+" TC returned",time:p.closedAt||"This session",sortTime:Date.parse(p.closedAtIso||"")||0,icon:ChartNoAxesCombined}));
 const openItems=positions.filter(p=>!p.aiManaged).map(p=>({id:"p"+p.id,title:"Practice position opened",detail:p.direction+" · "+p.market+" · "+money(p.amount)+" TC"+(p.aiCreditCost?" · "+p.aiCreditCost+" AC charged":""),time:p.time,sortTime:Date.parse(p.openedAt||"")||0,icon:ChartNoAxesCombined}));
 const ledgerItems=ledgerEntries.map(row=>{const amount=Number(row.amount_atoms||0),currency=row.currency||"TC",label=String(row.event_type||"Ledger update").replace(/[._]/g," ");return {id:"l"+row.transaction_id+currency,title:label.charAt(0).toUpperCase()+label.slice(1),detail:(amount>0?"+":"")+money(currency==="AC"?amount/2:amount)+" "+currency+" · verified ledger entry",time:row.created_at?new Date(row.created_at).toLocaleString([], {dateStyle:"medium",timeStyle:"short"}):"Recorded",sortTime:Date.parse(row.created_at||"")||0,icon:currency==="AC"?Sparkles:currency==="PXY"?CircleDollarSign:Layers3,tcDelta:currency==="TC"?amount:undefined,acDelta:currency==="AC"?amount/2:undefined}});
 const demoMissionItems=workspaceMode==="account"?[]:missions.filter(m=>m.done).map(m=>({id:"m"+m.id,title:"Mission completed",detail:m.title+" · +"+m.reward+" TC",time:"This session",sortTime:0,icon:Check}));
 const items=[...aiItems,...closedItems,...openItems,...(workspaceMode==="account"?ledgerItems:[]),...demoMissionItems].sort((x,y)=>(y.sortTime||0)-(x.sortTime||0));
